/**
 * EXPLODE - Itens
 *
 * Contrato de entrada:
 * {
 *   codigo_orcamento: string,
 *   orcamento_sharepoint_id: number,
 *   drive_file_id: string,
 *   orcamento: object,
 *   itens: array
 * }
 *
 * Contrato de saída:
 * Um item n8n por item do orçamento, contendo:
 * - contexto do orçamento;
 * - dados completos do item;
 * - array de tributos normalizado;
 * - vínculo pairedItem com a entrada.
 */

const entradas = $input.all();

if (entradas.length !== 1) {
  throw new Error(
    `EXPLODE - Itens esperava exatamente 1 orçamento por execução, mas recebeu ${entradas.length}.`
  );
}

const entrada = entradas[0]?.json ?? {};

/* -------------------------------------------------------------------------- */
/* Helpers                                                                    */
/* -------------------------------------------------------------------------- */

function texto(valor) {
  return String(valor ?? '').trim();
}

function numero(valor, padrao = null) {
  if (
    valor === null ||
    valor === undefined ||
    valor === ''
  ) {
    return padrao;
  }

  if (typeof valor === 'number') {
    return Number.isFinite(valor)
      ? valor
      : padrao;
  }

  let normalizado = String(valor)
    .trim()
    .replace(/\s/g, '');

  /*
   * Formatos tratados:
   * 1.234,56 → 1234.56
   * 1234,56  → 1234.56
   * 1234.56  → 1234.56
   */
  if (
    normalizado.includes('.') &&
    normalizado.includes(',')
  ) {
    normalizado = normalizado
      .replace(/\./g, '')
      .replace(',', '.');
  } else if (normalizado.includes(',')) {
    normalizado = normalizado.replace(',', '.');
  }

  const convertido = Number(normalizado);

  return Number.isFinite(convertido)
    ? convertido
    : padrao;
}

function inteiroPositivo(valor, padrao) {
  const convertido = numero(valor, padrao);

  if (
    !Number.isFinite(convertido) ||
    convertido <= 0
  ) {
    return padrao;
  }

  return Math.trunc(convertido);
}

function booleanoOuNulo(valor) {
  if (valor === true || valor === false) {
    return valor;
  }

  if (typeof valor === 'string') {
    const normalizado = valor
      .trim()
      .toUpperCase();

    if (
      normalizado === 'TRUE' ||
      normalizado === 'SIM'
    ) {
      return true;
    }

    if (
      normalizado === 'FALSE' ||
      normalizado === 'NAO' ||
      normalizado === 'NÃO'
    ) {
      return false;
    }
  }

  return null;
}

function primeiroTexto(...valores) {
  for (const valor of valores) {
    const convertido = texto(valor);

    if (convertido) {
      return convertido;
    }
  }

  return '';
}

/* -------------------------------------------------------------------------- */
/* Contexto do orçamento                                                      */
/* -------------------------------------------------------------------------- */

const fieldsSharePoint =
  entrada.fields &&
  typeof entrada.fields === 'object' &&
  !Array.isArray(entrada.fields)
    ? entrada.fields
    : {};

const orcamentoEntrada =
  entrada.orcamento &&
  typeof entrada.orcamento === 'object' &&
  !Array.isArray(entrada.orcamento)
    ? entrada.orcamento
    : {};

const orcamento = {
  ...fieldsSharePoint,
  ...orcamentoEntrada
};

const itens =
  Array.isArray(entrada.itens)
    ? entrada.itens
    : Array.isArray(entrada.Itens)
      ? entrada.Itens
      : [];

const codigoOrcamento = primeiroTexto(
  entrada.Codigo_Orcamento,
  entrada.codigo_orcamento,
  fieldsSharePoint.Codigo_Orcamento,
  orcamento.codigo_orcamento,
  orcamento.Codigo_Orcamento
);

const numeroOrcamento = primeiroTexto(
  orcamento.numero_orcamento,
  orcamento.Numero_Orcamento,
  fieldsSharePoint.Numero_Orcamento,
  entrada.Numero_Orcamento
);

const driveFileId = primeiroTexto(
  entrada.drive_file_id,
  entrada.DriveFileId,
  entrada.driveFileId,
  fieldsSharePoint.DriveFileId,
  orcamento.drive_file_id,
  orcamento.DriveFileId,
  orcamento.driveFileId
);

const orcamentoSharePointId = inteiroPositivo(
  entrada._referencia_orcamento_validada === true ? entrada.orcamento_sharepoint_id : null,
  null
);
if (entrada._referencia_orcamento_validada !== true) {
  throw new Error('EXPLODE - Itens: referência do orçamento não foi validada no SharePoint.');
}
if (!codigoOrcamento) {
  throw new Error(
    'EXPLODE - Itens: Codigo_Orcamento não foi localizado no contrato de entrada.'
  );
}

if (!orcamentoSharePointId) {
  throw new Error(
    `EXPLODE - Itens: ID do orçamento no SharePoint não localizado para ${codigoOrcamento}.`
  );
}

if (itens.length === 0) {
  return [];
}

/* -------------------------------------------------------------------------- */
/* Normalização tributária                                                    */
/* -------------------------------------------------------------------------- */

function normalizarTributo(
  tipo,
  aliquota,
  valor,
  origem = 'CAMPO_PADRAO'
) {
  const tipoNormalizado = texto(tipo).toUpperCase();

  if (!tipoNormalizado) {
    return null;
  }

  const aliquotaNormalizada = numero(aliquota, 0);
  const valorNormalizado = numero(valor, 0);

  if (
    aliquotaNormalizada === 0 &&
    valorNormalizado === 0
  ) {
    return null;
  }

  return {
    tipo: tipoNormalizado,
    aliquota_percentual: aliquotaNormalizada,
    valor: valorNormalizado,
    origem
  };
}

function montarTributos(item) {
  const tributos = [];

  const tributosPadrao = [
    normalizarTributo(
      'IPI',
      item.ipi_percentual,
      item.ipi_valor
    ),
    normalizarTributo(
      'ICMS',
      item.icms_percentual,
      item.icms_valor
    ),
    normalizarTributo(
      'ICMS_ST',
      item.icms_st_percentual,
      item.icms_st_valor
    ),
    normalizarTributo(
      'PIS',
      item.pis_percentual,
      item.pis_valor
    ),
    normalizarTributo(
      'COFINS',
      item.cofins_percentual,
      item.cofins_valor
    ),
    normalizarTributo(
      'ISS',
      item.iss_percentual,
      item.iss_valor
    )
  ];

  for (const tributo of tributosPadrao) {
    if (tributo) {
      tributos.push(tributo);
    }
  }

  const outrosImpostos =
    Array.isArray(item.outros_impostos)
      ? item.outros_impostos
      : [];

  for (const imposto of outrosImpostos) {
    if (
      !imposto ||
      typeof imposto !== 'object' ||
      Array.isArray(imposto)
    ) {
      continue;
    }

    const tributo = normalizarTributo(
      imposto.tipo,
      imposto.aliquota_percentual,
      imposto.valor,
      'OUTROS_IMPOSTOS'
    );

    if (tributo) {
      tributos.push(tributo);
    }
  }

  /*
   * Compatibilidade com entradas antigas que já tragam
   * um array tributos pronto.
   */
  const tributosRecebidos =
    Array.isArray(item.tributos)
      ? item.tributos
      : [];

  for (const imposto of tributosRecebidos) {
    if (
      !imposto ||
      typeof imposto !== 'object' ||
      Array.isArray(imposto)
    ) {
      continue;
    }

    const tributo = normalizarTributo(
      imposto.tipo ??
      imposto.tipo_tributo,

      imposto.aliquota_percentual ??
      imposto.aliquota,

      imposto.valor ??
      imposto.valor_tributo,

      imposto.origem ?? 'ARRAY_TRIBUTOS'
    );

    if (!tributo) {
      continue;
    }

    /*
     * Evita duplicar o mesmo imposto caso ele exista
     * nos campos individuais e no array tributos.
     */
    const duplicado = tributos.some(
      existente =>
        existente.tipo === tributo.tipo &&
        existente.aliquota_percentual ===
          tributo.aliquota_percentual &&
        existente.valor === tributo.valor
    );

    if (!duplicado) {
      tributos.push(tributo);
    }
  }

  return tributos;
}

/* -------------------------------------------------------------------------- */
/* Explosão dos itens                                                         */
/* -------------------------------------------------------------------------- */

const numerosUtilizados = new Set();

return itens.map((itemRecebido, index) => {
  const item =
    itemRecebido &&
    typeof itemRecebido === 'object' &&
    !Array.isArray(itemRecebido)
      ? itemRecebido
      : {};

  const numeroItem = inteiroPositivo(
    item.numero_item,
    index + 1
  );

  if (numerosUtilizados.has(numeroItem)) {
    throw new Error(
      `EXPLODE - Itens: numero_item duplicado (${numeroItem}) no orçamento ${codigoOrcamento}.`
    );
  }

  numerosUtilizados.add(numeroItem);

  const numeroItemFormatado =
    String(numeroItem).padStart(3, '0');

  const codigoItem =
    `${codigoOrcamento}-ITEM-${numeroItemFormatado}`;

  const tributos = montarTributos(item);

  return {
    json: {
      /*
       * Preserva integralmente o item recebido.
       */
      ...item,

      numero_item: numeroItem,
      codigo_item: codigoItem,

      codigo_orcamento: codigoOrcamento,
      orcamento_sharepoint_id:
        orcamentoSharePointId,
      drive_file_id: driveFileId,

      fornecedor: primeiroTexto(
        orcamento.fornecedor,
        orcamento.Fornecedor
      ),

      numero_orcamento:
        numeroOrcamento,

      cnpj_fornecedor: primeiroTexto(
        orcamento.cnpj_fornecedor,
        orcamento.CNPJ_Fornecedor
      ),

      impostos_inclusos_preco:
        booleanoOuNulo(
          item.impostos_inclusos_preco
        ),

      tributos,

      metadados_item: {
        indice_origem: index,
        quantidade_tributos:
          tributos.length,
        origem:
          entrada.metadados_processamento
            ?.origem || 'DESCONHECIDA'
      }
    },

    pairedItem: {
      item: 0
    }
  };
});

const entrada = $json || {};

function texto(valor) {
  return String(valor ?? '').trim();
}

function numero(valor, padrao = null) {
  if (
    valor === null ||
    valor === undefined ||
    valor === ''
  ) {
    return padrao;
  }

  if (typeof valor === 'number') {
    return Number.isFinite(valor)
      ? valor
      : padrao;
  }

  let normalizado = String(valor)
    .trim()
    .replace(/R\$/gi, '')
    .replace(/\s/g, '');

  if (
    normalizado.includes('.') &&
    normalizado.includes(',')
  ) {
    normalizado = normalizado
      .replace(/\./g, '')
      .replace(',', '.');
  } else if (normalizado.includes(',')) {
    normalizado = normalizado.replace(',', '.');
  }

  const convertido = Number(normalizado);

  return Number.isFinite(convertido)
    ? convertido
    : padrao;
}

function inteiro(valor, padrao = null) {
  const convertido = numero(valor, padrao);

  if (convertido === null) {
    return padrao;
  }

  return Math.trunc(convertido);
}

const codigoItem =
  texto(entrada.codigo_item);

const codigoOrcamento =
  texto(entrada.codigo_orcamento);

const orcamentoSharePointId =
  inteiro(
    entrada.orcamento_sharepoint_id,
    null
  );

if (!codigoItem) {
  throw new Error(
    'codigo_item não recebido no PREP - Itens.'
  );
}

if (!codigoOrcamento) {
  throw new Error(
    `codigo_orcamento não recebido para ${codigoItem}.`
  );
}

if (!orcamentoSharePointId) {
  throw new Error(
    `orcamento_sharepoint_id não recebido para ${codigoItem}.`
  );
}

const tributos = Array.isArray(entrada.tributos)
  ? entrada.tributos
  : [];

const fields = {
  Title: codigoItem,

  Codigo_Item: codigoItem,

  Numero_Item:
    inteiro(entrada.numero_item, null),

  Codigo_OrcamentoLookupId:
    orcamentoSharePointId,

  DriveFileId:
    texto(entrada.drive_file_id) || null,

  Fornecedor:
    texto(entrada.fornecedor) || null,

  Codigo_Fornecedor:
    texto(
      entrada.codigo_produto_fornecedor
    ) || null,

  Referencia_Fornecedor:
    texto(
      entrada.referencia_fornecedor
    ) || null,

  Descricao_Original:
    texto(
      entrada.descricao_original
    ) || null,

  Quantidade:
    numero(entrada.quantidade, null),

  Unidade_Original:
    texto(
      entrada.unidade_original
    ) || null,

  Preco_Unitario:
    numero(entrada.preco_unitario, null),

  Preco_Total:
    numero(entrada.preco_total, null),

  NCM:
    texto(entrada.ncm) || null,

  Material_Sugerido:
    texto(
      entrada.material_sugerido
    ) || null,

  Material_Aprovado:
    texto(
      entrada.material_aprovado
    ) || null,

  Status_Revisao:
    texto(
      entrada.status_revisao
    ).toUpperCase() || 'PENDENTE',

  Enviado_Historico:
    texto(
      entrada.enviado_historico
    ).toUpperCase() || 'NAO',

  Observacao_Item:
    texto(
      entrada.observacao_item
    ) || null
};

return {
  json: {
    codigo_item: codigoItem,
    codigo_orcamento: codigoOrcamento,

    orcamento_sharepoint_id:
      orcamentoSharePointId,

    drive_file_id:
      texto(entrada.drive_file_id),

    numero_item:
      inteiro(entrada.numero_item, null),

    tributos,

    fields
  }
};

const respostaLookup = $json || {};

const itemPreparado =
  $items("PREP - Itens")[0]?.json || {};

function texto(valor) {
  return String(valor ?? '').trim();
}

const registroEncontrado =
  Array.isArray(respostaLookup.value)
    ? respostaLookup.value[0]
    : null;

const itemSharePointId =
  registroEncontrado?.id
    ? Number(registroEncontrado.id)
    : null;

const itemExiste =
  Number.isFinite(itemSharePointId) &&
  itemSharePointId > 0;

return {
  json: {
    ...itemPreparado,

    item_existe: itemExiste,

    item_sharepoint_id:
      itemExiste
        ? itemSharePointId
        : null,

    acao_item:
      itemExiste
        ? 'PATCH'
        : 'POST'
  }
};

const decisao = $('CODE - Decidir Item').item.json;

// No PATCH, o ID já veio do LOOKUP
const itemSharePointId = Number(
  decisao.item_sharepoint_id || 0
);

if (!itemSharePointId) {
  throw new Error(
    `ID do item não encontrado no PATCH: ${decisao.codigo_item}`
  );
}

return [
  {
    json: {
      operacao_item: 'PATCH',

      item_sharepoint_id: itemSharePointId,

      codigo_item:
        decisao.codigo_item,

      codigo_orcamento:
        decisao.codigo_orcamento,

      orcamento_sharepoint_id:
        Number(decisao.orcamento_sharepoint_id),

      drive_file_id:
        decisao.drive_file_id || '',

      tributos:
        Array.isArray(decisao.tributos)
          ? decisao.tributos
          : []
    }
  }
];

const decisao = $('CODE - Decidir Item').item.json;
const respostaGraph = $json || {};

// No POST, o Graph retorna o ID criado
const itemSharePointId = Number(
  respostaGraph.id || 0
);

if (!itemSharePointId) {
  throw new Error(
    `ID do item não retornado no POST: ${decisao.codigo_item}`
  );
}

return [
  {
    json: {
      operacao_item: 'POST',

      item_sharepoint_id: itemSharePointId,

      codigo_item:
        decisao.codigo_item,

      codigo_orcamento:
        decisao.codigo_orcamento,

      orcamento_sharepoint_id:
        Number(decisao.orcamento_sharepoint_id),

      drive_file_id:
        decisao.drive_file_id || '',

      tributos:
        Array.isArray(decisao.tributos)
          ? decisao.tributos
          : []
    }
  }
];

const entrada = $input.first().json;

return [
  {
    json: {
      ...entrada,
      entrada_original: entrada
    }
  }
];

const item = $json;

const tributos = Array.isArray(item.tributos)
  ? item.tributos
  : [];

if (tributos.length === 0) {
  return [
    {
      json: {
        possui_tributo: false,

        codigo_item: item.codigo_item,
        item_sharepoint_id: Number(item.item_sharepoint_id),

        codigo_orcamento: item.codigo_orcamento,
        orcamento_sharepoint_id:
          Number(item.orcamento_sharepoint_id),

        drive_file_id: item.drive_file_id || ''
      }
    }
  ];
}

return tributos.map((tributo, indice) => {
  const tipo = String(
    tributo.tipo ||
    tributo.tipo_tributo ||
    'OUTRO'
  )
    .trim()
    .toUpperCase();

  return {
    json: {
      possui_tributo: true,

      codigo_tributo_item:
        `${item.codigo_item}-${tipo}`,

      codigo_item:
        item.codigo_item,

      item_sharepoint_id:
        Number(item.item_sharepoint_id),

      codigo_orcamento:
        item.codigo_orcamento,

      orcamento_sharepoint_id:
        Number(item.orcamento_sharepoint_id),

      drive_file_id:
        item.drive_file_id || '',

      tipo_tributo:
        tipo,

      aliquota_percentual:
        tributo.percentual ??
        tributo.aliquota_percentual ??
        null,

      valor_tributo:
        tributo.valor ??
        tributo.valor_tributo ??
        null,

      situacao_tributaria:
        tributo.situacao_tributaria ||
        'NAO_INFORMADO',

      base_calculo:
        tributo.base_calculo ??
        '',

      iniciar_loop_tributos: true,

      observacao_fiscal:
        tributo.observacao_fiscal ||
        '',

      indice_tributo:
        indice + 1
    }
  };
});

const j = $json;

const tiposPermitidos = [
  'PIS',
  'COFINS',
  'ICMS',
  'DIFAL',
  'IPI',
  'ISS',
  'OUTRO',
  'ICMS-ST'
];

const situacoesPermitidas = [
  'INCLUSO',
  'A_INCLUIR',
  'NAO_INFORMADO',
  'NAO_APLICA',
  'ISENTO'
];

const tipoRecebido = String(
  j.tipo_tributo || 'OUTRO'
)
  .trim()
  .toUpperCase();

const tipoTributo = tiposPermitidos.includes(tipoRecebido)
  ? tipoRecebido
  : 'OUTRO';

const situacaoRecebida = String(
  j.situacao_tributaria || 'NAO_INFORMADO'
)
  .trim()
  .toUpperCase();

const situacaoTributaria =
  situacoesPermitidas.includes(situacaoRecebida)
    ? situacaoRecebida
    : 'NAO_INFORMADO';

const fields = {
  Title: j.codigo_tributo_item,

  Codigo_Tributo_Item:
    j.codigo_tributo_item,

  Codigo_ItemLookupId:
    Number(j.item_sharepoint_id),

  Codigo_OrcamentoLookupId:
    Number(j.orcamento_sharepoint_id),

  Tipo_Tributo:
    tipoTributo,

  Situacao_Tributaria:
    situacaoTributaria,

  Status_Revisao:
    'PENDENTE'
};

if (j.drive_file_id) {
  fields.DriveFileId =
    String(j.drive_file_id);
}

if (
  j.aliquota_percentual !== null &&
  j.aliquota_percentual !== undefined &&
  j.aliquota_percentual !== ''
) {
  fields.Aliquota_Percentual =
    Number(j.aliquota_percentual);
}

if (
  j.valor_tributo !== null &&
  j.valor_tributo !== undefined &&
  j.valor_tributo !== ''
) {
  fields.Valor_Tributo =
    Number(j.valor_tributo);
}

if (
  j.base_calculo !== null &&
  j.base_calculo !== undefined &&
  j.base_calculo !== ''
) {
  fields.Base_Calculo =
    String(j.base_calculo);
}

if (j.observacao_fiscal) {
  fields.Observacao_Fiscal =
    String(j.observacao_fiscal);
}

return [
  {
    json: {
      ...j,
      fields
    }
  }
];

const preparado = $('PREP - Tributo').item.json;
const respostaLookup = $json || {};

const registros = Array.isArray(respostaLookup.value)
  ? respostaLookup.value
  : [];

const registroEncontrado =
  registros.length > 0
    ? registros[0]
    : null;

return [
  {
    json: {
      ...preparado,

      tributo_existe:
        Boolean(registroEncontrado),

      tributo_sharepoint_id:
        registroEncontrado
          ? Number(registroEncontrado.id)
          : null
    }
  }
];

