={{ (() => {
  const f = $json.fields || {};

  const body = {
    Title: f.Title,
    Codigo_Item: f.Codigo_Item,
    Numero_Item: f.Numero_Item,
    Codigo_OrcamentoLookupId: f.Codigo_OrcamentoLookupId,
    DriveFileId: f.DriveFileId,
    Fornecedor: f.Fornecedor,
    Codigo_Fornecedor: f.Codigo_Fornecedor,
    Referencia_Fornecedor: f.Referencia_Fornecedor,
    Descricao_Original: f.Descricao_Original,
    Quantidade: f.Quantidade,
    Unidade_Original: f.Unidade_Original,
    Preco_Unitario: f.Preco_Unitario,
    Preco_Total: f.Preco_Total,
    NCM: f.NCM,
    Material_Sugerido: f.Material_Sugerido,
    Material_AprovadoLookupId: f.Material_AprovadoLookupId,
    Status_Revisao: 'Pendente',
    Enviado_Historico: 'Não',
    Observacao_Item: f.Observacao_Item
  };

  return Object.fromEntries(
    Object.entries(body).filter(([key, value]) =>
      value !== null &&
      value !== undefined &&
      value !== ''
    )
  );
})() }}

