if (!codigoOrcamento) throw new Error('Contrato inválido: codigo_orcamento é obrigatório.');
if (!orcamentoSharePointId) throw new Error('Contrato inválido: orcamento_sharepoint_id deve ser um inteiro positivo.');
if (!Array.isArray(itens)) throw new Error('Contrato inválido: itens deve ser um array.');
